### Timing checks and reproducibility

MSFsc and the primary midpoint comparison use local clock time. Three retained nights cross a daylight-saving transition. As a check, we also calculate their midpoints using true elapsed UTC time and then convert back to local time. The affected midpoint changes are 30 minutes; the overall correlation remains **0.66** under either convention. All observed midsleep values lie between **00:18 and 11:06**, so the fixed noon cut does not split the recorded distribution.


::: {.cell}

```{.r .cell-code  code-fold="true" code-summary="Check waking-day labels, midnight handling, SD eligibility and daylight-saving transitions"}
sleep_diary_dst_audit <- sleep_diary_nights |>
  mutate(
    midpoint_utc = sleep_onset_utc +
      as.numeric(difftime(wake_utc, sleep_onset_utc, units = "secs")) / 2
  )
sleep_diary_dst_audit$elapsed_midpoint_local_label <- vapply(
  seq_len(nrow(sleep_diary_dst_audit)),
  function(i)
    format(
      sleep_diary_dst_audit$midpoint_utc[i],
      tz = sleep_diary_dst_audit$site_timezone[i],
      format = "%Y-%m-%d %H:%M:%S"
    ),
  character(1)
)
sleep_diary_dst_audit <- sleep_diary_dst_audit |>
  mutate(
    elapsed_midpoint_wall = as.POSIXct(
      elapsed_midpoint_local_label,
      tz = "UTC"
    ),
    elapsed_midpoint_hours = (as.numeric(elapsed_midpoint_wall) / 3600) %% 24,
    elapsed_minus_wall_minutes = (((elapsed_midpoint_hours -
      midsleep_hours +
      12) %%
      24) -
      12) *
      60
  )
sleep_diary_dst_sensitivity <- sleep_diary_dst_audit |>
  summarise(
    night_r_wall = stats::cor(msfsc_unwrapped_hours, midsleep_unwrapped_hours),
    night_r_elapsed = stats::cor(
      msfsc_unwrapped_hours,
      ((elapsed_midpoint_hours + 12) %% 24) - 12
